from lxml import etree
from io import StringIO

from django.http import HttpResponse


def xpath_query(request):
    '''
    Get the `xpath` value from the GET request,
    get the 'xml' value from the GET request,
    construct and parse the xml payload,
    return the result of the XPath query "/tag[@id={}]" format from the parsed xml
    '''
    xpath_value = request.GET.get('xpath')
    xml_payload = request.GET.get('xml')

    if not xpath_value or not xml_payload:
        return HttpResponse("Missing required parameters", status=400)

    try:
        # Parse the XML payload
        parser = etree.XMLParser(remove_comments=True)
        tree = etree.parse(StringIO(xml_payload), parser)

        # Perform the XPath query
        result = tree.xpath(xpath_value)

        # Format the result as a string
        formatted_result = '\n'.join([etree.tostring(elem, pretty_print=True).decode() for elem in result])

        return HttpResponse(formatted_result, content_type='text/xml')

    except etree.XMLSyntaxError as e:
        return HttpResponse(f"Invalid XML: {e}", status=400)
    except Exception as e:
        return HttpResponse(f"An error occurred: {e}", status=500)
```

